        claims.put("jti", jti);
        return this;
    }

    public JwtBuilder claim(String name, Object value) {
        if (value == null) {
            claims.remove(name);
        } else {
            claims.put(name, value);
        }
        return this;
    }

    public JwtBuilder addClaims(Map<String, Object> claimsToAdd) {
        if (claimsToAdd != null) {
            claims.putAll(claimsToAdd);
        }
        return this;
    }

    public JwtBuilder setClaims(Map<String, Object> claims) {
        this.claims.clear();
        if (claims != null) {
            this.claims.putAll(claims);
        }
        return this;
    }

    public JwtBuilder signWith(SecretKey key, SignatureAlgorithm alg) {
        if (key == null) {
            throw new IllegalArgumentException("Signing key cannot be null.");
        }
        if (alg == null) {
            throw new IllegalArgumentException("SignatureAlgorithm cannot be null.");
        }
        this.key = key;
        this.algorithm = alg;
        return this;
